// function: install_breakpoint
fn install_breakpoint (pid : i32 , address : u64) -> Result < u64 , Box < dyn std :: error :: Error > > { unsafe { let original = ptrace (PTRACE_PEEKTEXT , pid , address as * mut libc :: c_void , std :: ptr :: null_mut :: < libc :: c_void > () ,) ; if original == - 1 { return Err ("Failed to read memory" . into ()) ; } let breakpoint = (original & ! 0xFF) | 0xCC ; if ptrace (PTRACE_POKETEXT , pid , address as * mut libc :: c_void , breakpoint as * mut libc :: c_void ,) == - 1 { return Err ("Failed to install breakpoint" . into ()) ; } Ok (original as u64) } }

