fn restore_instruction (pid : i32 , address : u64 , original : u64 ,) -> Result < () , Box < dyn std :: error :: Error > > { unsafe { if ptrace (PTRACE_POKETEXT , pid , address as * mut libc :: c_void , original as * mut libc :: c_void) == - 1 { return Err ("Failed to restore instruction" . into ()) ; } } Ok (()) }

