// function: calculate_monster_signature
fn calculate_monster_signature (bytes : & [u8]) -> Vec < u64 > { let mut signature = Vec :: new () ; for & prime in & MONSTER_PRIMES { let count = count_prime_patterns (bytes , prime) ; signature . push (count) ; } signature }

// function: count_prime_patterns
