// function: find_morse_critical_points
fn find_morse_critical_points (bytes : & [u8]) -> Vec < f64 > { let mut critical_points = Vec :: new () ; let heights : Vec < f64 > = bytes . iter () . map (| & b | b as f64) . collect () ; for i in 1 .. heights . len () - 1 { let prev = heights [i - 1] ; let curr = heights [i] ; let next = heights [i + 1] ; if curr > prev && curr > next { critical_points . push (curr) ; } else if curr < prev && curr < next { critical_points . push (curr) ; } else if (curr - prev) . abs () < 1.0 && (curr - next) . abs () < 1.0 { critical_points . push (curr) ; } } critical_points }

