fn main () { let data : Value = serde_json :: from_str (& fs :: read_to_string ("path_signatures.json") . expect ("Missing path_signatures.json") ,) . expect ("Invalid JSON") ; let signatures = data ["path_signatures"] . as_object () . expect ("Missing path_signatures object") ; let analysis_files : Vec < String > = fs :: read_to_string ("all_analysis_files.txt") . expect ("Missing all_analysis_files.txt") . lines () . map (| s | s . to_string ()) . collect () ; let mut class_ast_items : HashMap < String , Vec < String > > = HashMap :: new () ; for file_path in & analysis_files { if let Ok (content) = fs :: read_to_string (file_path) { if let Ok (json_data) = serde_json :: from_str :: < Value > (& content) { extract_items_by_signature (& json_data , signatures , & mut class_ast_items , "") ; } } } for (class_ast , items) in & class_ast_items { if items . len () > 5 { let filename = format ! ("rustc_driver_impl/src/lib.{}.rs" , class_ast . replace (" " , "_")) ; let content = items . join ("\n\n") ; fs :: write (& filename , content) . expect ("Failed to write file") ; println ! ("📝 Created {} with {} items" , filename , items . len ()) ; } } }

// function: extract_items_by_signature
fn extract_items_by_signature (json : & Value , signatures : & serde_json :: Map < String , Value > , class_ast_items : & mut HashMap < String , Vec < String > > , current_path : & str ,) { match json { Value :: Object (obj) => { for (key , value) in obj { let new_path = if current_path . is_empty () { key . clone () } else { format ! ("{}.{}" , current_path , key) } ; if let Some (sig_val) = signatures . get (& new_path) { let signature = sig_val . as_u64 () . unwrap_or (0) as u128 ; let complexity_class = classify_signature (signature) ; let ast_type = extract_ast_type_from_path (& new_path) ; let class_key = format ! ("{} {}" , complexity_class , ast_type) ; if let Some (code) = extract_rust_code (value) { class_ast_items . entry (class_key) . or_default () . push (code) ; } } extract_items_by_signature (value , signatures , class_ast_items , & new_path) ; } } Value :: Array (arr) => { for (i , item) in arr . iter () . enumerate () { let new_path = format ! ("{}[{}]" , current_path , i) ; extract_items_by_signature (item , signatures , class_ast_items , & new_path) ; } } _ => { } } }

// function: classify_signature
fn classify_signature (signature : u128) -> String { match signature { 1 ..= 10 => "simple" . to_string () , 11 ..= 20 => "compound" . to_string () , 21 ..= 30 => "complex" . to_string () , 31 ..= 40 => "nested" . to_string () , 41 ..= 50 => "deep" . to_string () , 51 ..= 60 => "ultra" . to_string () , 61 ..= 70 => "extreme" . to_string () , _ => "overflow" . to_string () , } }

// function: extract_ast_type_from_path
fn extract_ast_type_from_path (path : & str) -> String { let segments : Vec < & str > = path . split ('.') . collect () ; let mut type_candidates = HashMap :: new () ; for segment in segments { if ! segment . chars () . all (| c | c . is_numeric () || c == '[' || c == ']') { * type_candidates . entry (segment) . or_insert (0) += 1 ; } } type_candidates . into_iter () . max_by_key (| (_ , count) | * count) . map (| (ast_type , _) | ast_type . to_string ()) . unwrap_or_else (| | "unknown" . to_string ()) }

// function: compute_enum_modular_key
fn compute_enum_modular_key (name : & str , address : u64) -> String { let name_hash = name . bytes () . map (| b | b as u64) . sum :: < u64 > () ; let combined = name_hash . wrapping_add (address) ; let level = (combined % 37) + 1 ; let weight = if combined % 3 == 0 { 2 } else if combined % 3 == 1 { 4 } else { 6 } ; let character = if combined % 2 == 0 { "12" } else { "11" } ; let orbit = ((combined % 26) as u8 + b'a') as char ; format ! ("{}.{}.{}.{}" , level , weight , character , orbit) }

// function: count_enum_usage
fn count_enum_usage (binary : & [u8] , enum_address : u64) -> usize { let mut count = 0 ; let addr_bytes = enum_address . to_le_bytes () ; for window in binary . windows (8) { if window == addr_bytes { count += 1 ; } } count }

// function: calculate_module_hotness
fn calculate_module_hotness (name : & str , usage_count : usize , nesting_depth : usize) -> f64 { let base_hotness = usage_count as f64 ; let depth_multiplier = 1.0 + (nesting_depth as f64 * 0.1) ; let topic_multiplier = if name . contains ("error") || name . contains ("Error") { 2.0 } else if name . contains ("Option") || name . contains ("Result") { 3.0 } else if name . contains ("io") || name . contains ("net") { 1.5 } else { 1.0 } ; base_hotness * depth_multiplier * topic_multiplier }

// function: extract_variant_signatures
fn extract_variant_signatures (name : & str) -> Vec < String > { let mut variants = Vec :: new () ; if name . contains ("Option") { variants . push ("Some" . to_string ()) ; variants . push ("None" . to_string ()) ; } else if name . contains ("Result") { variants . push ("Ok" . to_string ()) ; variants . push ("Err" . to_string ()) ; } else if name . contains ("Ordering") { variants . push ("Less" . to_string ()) ; variants . push ("Equal" . to_string ()) ; variants . push ("Greater" . to_string ()) ; } variants }

